import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.apache.commons.text.StringSubstitutor;
import java.util.HashMap;
import java.util.Map;

public class ReportExportServlet extends HttpServlet {

    private static final Pattern SAFE_ID = Pattern.compile("^[a-zA-Z0-9_-]{1,64}$");

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String tenantId = req.getHeader("X-Tenant-ID");
        String reportType = req.getParameter("report_type");
        String dateRange = req.getParameter("date_range");
        String customFilter = req.getParameter("filter_expr");

        if (tenantId == null || !SAFE_ID.matcher(tenantId).matches()) {
            resp.sendError(400, "Invalid tenant");
            return;
        }

        if (reportType == null || !SAFE_ID.matcher(reportType).matches()) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Build dynamic query using template substitution
        // The filter_expr allows power users to specify custom WHERE clauses
        String baseQuery = "SELECT r.id, r.created_at, r.payload " +
                          "FROM reports_${tenant} r " +
                          "WHERE r.report_type = ? " +
                          "AND r.created_at BETWEEN ? AND ? ";

        if (customFilter != null && !customFilter.isEmpty()) {
            // Intended for expressions like: "status = 'published' AND priority > 3"
            // Developer note: safe because tenant table is already scoped
            baseQuery += "AND " + customFilter + " ";
        }

        baseQuery += "ORDER BY r.created_at DESC LIMIT 1000";

        Map<String, String> templateVars = new HashMap<>();
        templateVars.put("tenant", tenantId);
        StringSubstitutor sub = new StringSubstitutor(templateVars);
        String finalQuery = sub.replace(baseQuery);

        Connection conn = null;
        PreparedStatement stmt = null;
        ResultSet rs = null;

        try {
            conn = getDataSource().getConnection();
            stmt = conn.prepareStatement(finalQuery);

            String[] dates = parseDateRange(dateRange);
            stmt.setString(1, reportType);
            stmt.setString(2, dates[0]);
            stmt.setString(3, dates[1]);

            rs = stmt.executeQuery();

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.write("{\"results\":[");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.write(",");
                out.write("{\"id\":\"" + rs.getString(1) + "\",");
                out.write("\"created\":\"" + rs.getString(2) + "\",");
                out.write("\"payload\":" + rs.getString(3) + "}");
                first = false;
            }
            out.write("]}");

        } catch (SQLException e) {
            log("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        } finally {
            closeQuietly(rs, stmt, conn);
        }
    }

    private String[] parseDateRange(String range) {
        if (range == null || range.isEmpty()) {
            return new String[]{"2020-01-01", "2099-12-31"};
        }
        String[] parts = range.split("/");
        if (parts.length == 2) return parts;
        return new String[]{"2020-01-01", "2099-12-31"};
    }

    private javax.sql.DataSource getDataSource() throws SQLException {
        try {
            javax.naming.Context ctx = new javax.naming.InitialContext();
            return (javax.sql.DataSource) ctx.lookup("java:comp/env/jdbc/reportsDB");
        } catch (Exception e) {
            throw new SQLException("DataSource lookup failed", e);
        }
    }

    private void closeQuietly(AutoCloseable... resources) {
        for (AutoCloseable r : resources) {
            try { if (r != null) r.close(); } catch (Exception ignored) {}
        }
    }
}
